import { Component, EventEmitter, Input, Output, output } from '@angular/core';
import { NotificationsService } from '../../services/notifications.service';
import { IconComponent } from '../icon/icon.component';
import { ButtonComponent } from '../button/button.component';
import { AvatarComponent } from '../avatar/avatar.component';
import { notification } from '../../interfaces/notification.interface';
import { NotificationPipe } from '../../../userpanel/pips/notification.pip';
import { Router } from '@angular/router';
import { CommonfunctionService } from '../../../core/utility/commonfunction.service';
import { CommunicationService } from '../../services/communication/communication.service';
import { Subscription } from 'rxjs';
import { SecureStorageService } from '../../../core/services/storage/secure-storage.service';
import { MatTooltipModule } from '@angular/material/tooltip';
import { TostbarService } from '../../../core/services/tost/tostbar.service';

@Component({
  selector: 'notifications',
  standalone: true,

  imports: [IconComponent, ButtonComponent, AvatarComponent, NotificationPipe, MatTooltipModule],
  templateUrl: './notifications.component.html',
  styleUrl: './notifications.component.scss'
})
export class NotificationsComponent {

  @Output() clickevnts = new EventEmitter();

  @Input() nCaseid: string = null;
  notificationlist: notification[] = [];
  /** Server list and client list kept separate so we can re-merge on either change. */
  private serverList: notification[] = [];
  private clientList: notification[] = [];
  evsubscription: Subscription;
  private clientSub?: Subscription;

  constructor(private NotificationS: NotificationsService, private cm: CommonfunctionService,
    private CMS: CommunicationService, private router: Router, private tost: TostbarService) {

    this.checkEventSub()
  }


  async checkEventSub() {
    this.evsubscription = this.CMS.functionCalled$.subscribe(async (data) => {
      if (data && data.event == 'NOTIFICATION' && data.data.nCaseid == this.nCaseid) {
        this.NotificationS._isNotification.next(true);
        setTimeout(() => {          
          this.ngOnInit()
        }, 500);
      }
    })
  }


  async ngOnDestroy() {
    this.evsubscription.unsubscribe();
    this.clientSub?.unsubscribe();
  }

  async ngOnInit() {
    this.serverList = (await this.getNotification(this.nCaseid)) || [];
    this.clientSub = this.NotificationS.clientNotifications$.subscribe(list => {
      this.clientList = list || [];
      this.refreshList();
    });
    this.refreshList();
  }

  /** Display list = client (newest, most relevant) on top, then server. */
  private refreshList(): void {
    this.notificationlist = [...this.clientList, ...this.serverList];
  }


  async getNotification(nCaseid) {
    let res: any = await this.NotificationS.getNotifcationList(nCaseid);
    return res || [];
  }


  remove(x) {
    const id = String(x.nNTid ?? '');
    if (id.startsWith('client-')) {
      this.NotificationS.removeClientNotification(id);
      return;
    }
    this.NotificationS.deleteNotification(this.nCaseid, x.nNTid);
    this.serverList = this.serverList.filter(y => y.nNTid != x.nNTid);
    this.refreshList();
  }


  goto(x: notification, e: any) {
    try {
      // Final-transcript-published client notification — jump to Evidence so
      // the user can find the new published copy in the Transcript folder.
      if (x.cType == 'TS-PUBLISH') {
        this.cm.goto('/myfiles/filesaction', { id: this.nCaseid });
        this.close();
        return;
      }
      if (x.cType == 'PRESENT-START' || x.cType == 'PRESENT-USER-ADDED') {
        if (x.nPresentid) {
          if (['I', 'B', 'C'].includes(x.cPresentStatus)) {
            this.tost.error('Presentation Ended')
            return;
          }
          this.router.navigateByUrl(
            `/individual/doc/${encodeURIComponent(
              JSON.stringify([[], this.nCaseid, x.nPresentid])
            )}`
          );
        }
      }
      if (['FS', 'DS', 'WS', 'LS'].includes(x.cType)) {
        this.openLinks(x)
      }
      if (['CS'].includes(x.cType)) {
        this.CMS.callFunction({ type: 'CHANGE-SECTION', cFoldertype: 'CB' })
        setTimeout(() => {
          this.CMS.callFunction({ type: 'VIEW-SHARE', nUserid: x.nRefuserid })
        }, 200);
      }
      if (x.nUPid) {
        this.openFolder(x.nUPid)
      }
    } catch (error) {

    }


  }


  openLinks(x: notification) {
    const bundledetailid = x.cType == 'LS' ? x.nBundledetailid : (x.cType == 'FS' ? x.nFBundledetailid : (x.cType == 'DS' ? x.nDBundledetailid : x.nWBundledetailid));

    if (!bundledetailid) return;
    // window.open(`${location.origin}/individual/doc/${encodeURIComponent(JSON.stringify([[[bundledetailid, 1, 0, x.nFSid || null, x.nDocid || null, x.nWebid || null]], this.nCaseid]))}`);


    this.cm.openHyperLinkFile(bundledetailid, this.nCaseid, null, null, false, 1, null, x.nFSid || null, x.nDocid || null, x.nWebid || null)

  }

  clearAll() {
    this.NotificationS.deleteNotification(this.nCaseid);
    this.NotificationS.clearClientNotifications();
    this.serverList = [];
    this.refreshList();
  }

  close() {
    this.clickevnts.emit('close');
  }


  openFolder(nUPid) {
    if (window.location.href.includes('/myfiles/filesaction')) {
      this.CMS.callFunction({ event: 'SHOW-UPLOAD', nUPid: nUPid })
    } else {
      this.cm.goto('/myfiles/filesaction', { id: this.nCaseid })
      setTimeout(() => {
        this.CMS.callFunction({ event: 'SHOW-UPLOAD', nUPid: nUPid })
      }, 50);
    }
    this.close();
  }

}
